// LEGACY C++03 Specification
// Runtime checks enforced if exception escapes
// Optimization potential limited
void legacy_operation() throw();

// C++11/14/17 NOEXCEPT
// Compile-time guarantee: Allows compiler to omit
// expensive stack unwinding preparation paths
void optimized_operation() noexcept;

// Conditional noexcept based on underlying types
template <typename T>
void call_T(T t) noexcept(noexcept(t.call()));

// Critical for efficient Move Semantics in containers
struct Resource {
    Resource(Resource&& other) noexcept;
    Resource& operator=(Resource&& other) noexcept;
};
